namespace ghidra.framework.options;












using org.jdom2;

using ghidra.util;
using ghidra.util.bean.opteditor;
using ghidra.util.classfinder;
using ghidra.util.exception;

/**
 * Class to manage a set of option name/value pairs for a category.
 *
 * <p>The values may be primitives or {@link WrappedOption}s that are containers for primitive
 * components.
 *
 * <p>The name/value pair has an owner so that the option name can be removed from the Options
 * object when it is no longer being used.
 *
 * <p>Note: Property Names can have {@link Options#DELIMITER} characters to create a hierarchy.
 * So too can sub-options accessed via {@link #getOptions(String)}.
 *
 * <p>The Options Dialog shows the delimited hierarchy in tree format.
 */
public class ToolOptions : AbstractOptions {

	private static readonly string CLASS_ATTRIBUTE = "CLASS";
	private static readonly string NAME_ATTRIBUTE = "NAME";
	private static readonly string WRAPPED_OPTION_NAME = "WRAPPED_OPTION";
	private static readonly string CLEARED_VALUE_ELEMENT_NAME = "CLEARED_VALUE";

	public static readonly string LAST_REGISTERED_DATE_ATTIBUTE = "LAST_REGISTERED";
	public static readonly DateTimeFormatter LAST_REGISTERED_DATE_FORMATTER =
		DateTimeFormatter.ISO_LOCAL_DATE;

	public static readonly Set<Class<object>> PRIMITIVE_CLASSES = buildPrimitiveClassSet();
	public static readonly Set<Class<object>> WRAPPABLE_CLASSES = buildWrappableClassSet();

	public static readonly string XML_ELEMENT_NAME = "CATEGORY";

	private static Set<Class<object>> buildPrimitiveClassSet() {
		HashSet<Class<object>> set = new();
		set.add(typeof(Byte));
		set.add(typeof(Short));
		set.add(typeof(Integer));
		set.add(typeof(Long));
		set.add(typeof(Float));
		set.add(typeof(Double));
		set.add(typeof(Boolean));
		set.add(typeof(string));
		return set;
	}

	private static Set<Class<object>> buildWrappableClassSet() {
		HashSet<Class<object>> set = new();
		set.add(typeof(Color));
		set.add(typeof(Font));
		set.add(typeof(KeyStroke));
		set.add(typeof(File));
		return set;
	}

	public ToolOptions(string name) : base(name)
    {
	}

	public ToolOptions copy() {
		return new ToolOptions(getXmlRoot(true));
	}

	/**
	 * Construct a new Options object from the given XML element.
	 * @param root XML that contains the set of options to restore
	 */
	public ToolOptions(Element root) : this(root.getAttributeValue(NAME_ATTRIBUTE))
    {

		AttributedSaveState saveState = new AttributedSaveState(root);

		readNonWrappedOptions(saveState);

		try {
			readWrappedOptions(root);
		}
		catch (ReflectiveOperationException exc) {
			Msg.error(this, "Unexpected Exception: " + exc.getMessage(), exc);
		}
	}

	private void readNonWrappedOptions(AttributedSaveState saveState) {
		foreach (string optionName in saveState.getNames()) {
			object @object = saveState.getObject(optionName);
			OptionType type = OptionType.getOptionType(@object);
			Option option = createUnregisteredOption(optionName, type, null);
			option.doSetCurrentValue(@object);  // use doSet versus set so that it is not registered

			LocalDate date = getLastRegisteredDateString(saveState, optionName);
			option.setLastRegisteredDate(date);

			valueMap.put(optionName, option);
		}
	}

	private LocalDate getLastRegisteredDateString(AttributedSaveState saveState,
			string optionName) {

		// Get the last registered date.  No date implies an old xml format.
		Map<string, string> attrs = saveState.getAttributes(optionName);
		if (attrs != null) {
			string dateString = attrs.get(LAST_REGISTERED_DATE_ATTIBUTE);
			if (dateString != null) {
				return LocalDate.parse(dateString, LAST_REGISTERED_DATE_FORMATTER);
			}
		}

		return LocalDate.now();
	}

	private void readWrappedOptions(Element root)
    {

		Iterator<object> it = root.getChildren(WRAPPED_OPTION_NAME).iterator();
		while (it.hasNext()) {

			Element element = (Element) it.next();
			List<object> children = element.getChildren();
			if (children.isEmpty()) {
				continue; // shouldn't happen
			}

			Class<WrappedOption> c =
				ClassSearcher.forNameSafe(element.getAttributeValue(CLASS_ATTRIBUTE),
					typeof(WrappedOption), getClass().getClassLoader());
			Constructor<WrappedOption> constructor = c.getDeclaredConstructor();
			WrappedOption wo = constructor.newInstance();
			wo.readState(new SaveState(element));
			if (wo is WrappedCustomOption wrappedCustom && !wrappedCustom.isValid()) {
				continue;
			}

			if (wo is WrappedKeyStroke wrappedKs) {
				wo = wrappedKs.toWrappedActionTrigger();
			}

			string optionName = element.getAttributeValue(NAME_ATTRIBUTE);
			Option option = createUnregisteredOption(optionName, wo.getOptionType(), null);
			valueMap.put(optionName, option);

			Element child = (Element) children.get(0);
			string elementName = child.getName();
			if (CLEARED_VALUE_ELEMENT_NAME.equals(elementName)) {
				// a signal that the default option value has been cleared
				option.doSetCurrentValue(null); // use doSet so that it is not registered
			}
			else {
				option.doSetCurrentValue(wo.getObject()); // use doSet so that it is not registered
			}

			// Get the last registered date.  No date implies an old xml format.
			LocalDate date = LocalDate.now();
			string dateString = element.getAttributeValue(LAST_REGISTERED_DATE_ATTIBUTE);
			if (dateString != null) {
				date = LocalDate.parse(dateString, LAST_REGISTERED_DATE_FORMATTER);
			}

			option.setLastRegisteredDate(date);
		}
	}

	/**
	 * Return an XML element for the option names and values.
	 * Note: only those options which have been explicitly set
	 * will be included.
	 *
	 * @param includeDefaultBindings true to include default key binding values in the xml
	 * @return the xml root element
	 */
	public Element getXmlRoot(bool includeDefaultBindings) {

		AttributedSaveState saveState = new AttributedSaveState(XML_ELEMENT_NAME);

		writeNonWrappedOptions(includeDefaultBindings, saveState);

		Element root = saveState.saveToXml();
		root.setAttribute(NAME_ATTRIBUTE, name);

		writeWrappedOptions(includeDefaultBindings, root);

		return root;
	}

	private void writeNonWrappedOptions(bool includeDefaultBindings,
			AttributedSaveState saveState) {
		foreach (string optionName in valueMap.keySet()) {
			Option option = valueMap.get(optionName);
			if (includeDefaultBindings || !option.isDefault()) {
				writeNonWrappedOption(saveState, optionName, option);
			}
		}
	}

	private void writeNonWrappedOption(AttributedSaveState saveState, string optionName,
			Option option) {
		object value = option.getValue(null);
		if (!isSupportedBySaveState(value)) {
			return;
		}

		saveState.putObject(optionName, value);

		LocalDate date = option.getLastRegisteredDate();
		string dateString = date.format(LAST_REGISTERED_DATE_FORMATTER);
		Map<string, string> attrs = Map.of(LAST_REGISTERED_DATE_ATTIBUTE, dateString);
		saveState.addAttributes(optionName, attrs);
	}

	private void writeWrappedOptions(bool includeDefaultBindings, Element root) {
		foreach (string optionName in valueMap.keySet()) {
			Option option = valueMap.get(optionName);
			if (option is ThemeColorOption || option is ThemeFontOption) {
				// theme values are saved by the theme, no need to save them to the options
				continue;
			}

			if (includeDefaultBindings || !option.isDefault()) {
				writeWrappedOption(root, optionName, option);
			}
		}
	}

	private void writeWrappedOption(Element root, string optionName, Option option) {
		object value = option.getCurrentValue();
		if (isSupportedBySaveState(value)) {
			return; // handled above
		}

		WrappedOption wrappedOption = wrapOption(option);
		if (wrappedOption == null) {
			return; // cannot write an option without a value to determine its type
		}

		SaveState ss = new SaveState(WRAPPED_OPTION_NAME);
		Element element = null;
		if (value == null) {
			// Handle the null case ourselves, not using the wrapped option (and when
			// reading from xml) so the logic does not need to be in each wrapped option
			element = ss.saveToXml();
			element.addContent(new Element(CLEARED_VALUE_ELEMENT_NAME));
		}
		else {
			wrappedOption.writeState(ss);
			element = ss.saveToXml();
		}

		element.setAttribute(NAME_ATTRIBUTE, optionName);

		string className = wrappedOption.GetType().getName();
		element.setAttribute(CLASS_ATTRIBUTE, className);

		LocalDate date = option.getLastRegisteredDate();
		string dateString = date.format(LAST_REGISTERED_DATE_FORMATTER);
		element.setAttribute(LAST_REGISTERED_DATE_ATTIBUTE, dateString);

		root.addContent(element);
	}

	private bool isSupportedBySaveState(object obj) {
		if (obj == null) {
			return false;
		}
		if (obj is Enum) {
			return true;
		}
		if (obj is byte[]) {
			return true;
		}
		return PRIMITIVE_CLASSES.contains(obj.GetType());

	}

	private WrappedOption wrapOption(Option option) {

		object value = null;
		value = option.getCurrentValue();
		if (value == null) {
			value = option.getDefaultValue();
		}

		if (value == null) {
			// nothing to wrap
			return null;
		}

		if (value is CustomOption) {
			return new WrappedCustomOption((CustomOption) value);
		}
		if (value is Color) {
			return new WrappedColor((Color) value);
		}
		if (value is Font) {
			return new WrappedFont((Font) value);
		}
		if (value is KeyStroke) {
			return new WrappedKeyStroke((KeyStroke) value);
		}
		if (value is ActionTrigger) {
			return new WrappedActionTrigger((ActionTrigger) value);
		}
		if (value is File) {
			return new WrappedFile((File) value);
		}
		if (value is Date) {
			return new WrappedDate((Date) value);
		}
		throw new AssertException(
			"Attempted to wrap object of unexpected class type: " + value.GetType());
	}

	/**
	 * Add the options change listener. NOTE: The Options uses
	 * WeakReferences to manage the listeners; this means that you must supply a
	 * listener and maintain a handle to it, or else the listener will be
	 * garbage collected and will never get called. So for this reason, do
	 * <i>not</i> create the listener in an anonymous inner class.
	 * @param l listener to add
	 */
	public void addOptionsChangeListener(OptionsChangeListener l) {
		listeners.add(l);
	}

	public void takeListeners(ToolOptions oldOptions) {
		listeners = oldOptions.listeners;
		oldOptions.listeners = null;
	}

	/**
	 * Remove the options change listener.
	 * @param l listener to remove
	 */
	public void removeOptionsChangeListener(OptionsChangeListener l) {
		listeners.remove(l);
	}

	/**
	 * Check each option to ensure that an owner is still registered for it;
	 * if there is no owner, then remove the option.
	 */
	public void removeUnusedOptions() {
		List<string> optionNames = new(valueMap.keySet());
		foreach (string optionName in optionNames) {
			Option optionState = valueMap.get(optionName);
			if (optionState.hasExpired()) {
				removeOption(optionName);
			}
		}
	}

	/**
	 * Adds all the options name/value pairs to this Options.
	 * @param newOptions the new options into which the current options values will be placed
	 */
	public void copyOptions(Options newOptions) {
		List<string> optionNames = newOptions.getOptionNames();
		foreach (string optionName in optionNames) {
			object value = newOptions.getObject(optionName, null);
			if (value != null) {
				putObject(optionName, value);
			}
		}
	}

	/* @Override */
	public int hashCode() {
		return name.hashCode();
	}

	/* @Override */
	public bool equals(object obj) {
		if (this == obj) {
			return true;
		}
		if (obj == null) {
			return false;
		}
		if (getClass() != obj.GetType()) {
			return false;
		}
		ToolOptions other = (ToolOptions) obj;
		if (!SystemUtilities.isEqual(name, other.name)) {
			return false;
		}

		List<string> optionNames = getOptionNames();
		List<string> otherOptionNames = other.getOptionNames();
		if (optionNames.size() != otherOptionNames.size()) {
			return false;
		}
		object dummy = new object();
		foreach (string string in optionNames) {
			object myValue = getObject(string, dummy);
			object otherValue = other.getObject(string, dummy);
			if (!SystemUtilities.isEqual(myValue, otherValue)) {
				return false;
			}
		}
		return true;
	}

	public void validateOptions() {
		if (!SystemUtilities.isInDevelopmentMode()) {
			// Only complain if in development mode - it appears normal that some options
			// are not registered (e.g., Navigation marker enablement)
			return;
		}

		Set<string> keySet = valueMap.keySet();
		foreach (string propertyName in keySet) {
			Option optionState = valueMap.get(propertyName);
			if (optionState.isRegistered() || optionState.wasRegisteredInPreviousSession()) {
				continue;
			}

			// getting here means that this option was used in the current tool session, but was not
			// registered this session or in a previous session
			Msg.warn(this,
				"Unregistered property \"" + propertyName + "\" in Options \"" + name +
					"\"\n     " + optionState.getInceptionInformation());
		}
	}

	public void registerOptions(ToolOptions oldOptions) {
		Set<string> optionNameSet = oldOptions.valueMap.keySet();
		foreach (string optionName in optionNameSet) {
			Option option = oldOptions.valueMap.get(optionName);
			if (option.isRegistered()) {
				registerOption(optionName, option.getOptionType(), option.getDefaultValue(),
					option.getHelpLocation(), option.getDescription());
			}
		}
	}

	private static class ToolOption : Option {
		private object currentValue;

		ToolOption(string name, OptionType type, string description, HelpLocation helpLocation,
				object defaultValue, bool isRegistered, PropertyEditor editor) : base(name, type, description, helpLocation, defaultValue, isRegistered, editor)
    {

			this.currentValue = defaultValue;
		}

		/* @Override */
		public object getCurrentValue() {
			return currentValue;
		}

		/* @Override */
		public void doSetCurrentValue(object value) {
			currentValue = value;
		}
	}

	/* @Override */
	protected Option createRegisteredOption(string optionName, OptionType type, string description,
			HelpLocation help, object defaultValue, PropertyEditor editor) {
		return new ToolOption(optionName, type, description, help, defaultValue, true, editor);
	}

	/* @Override */
	protected Option createUnregisteredOption(string optionName, OptionType type,
			object defaultValue) {

		if (type == OptionType.KEYSTROKE_TYPE) {
			// convert key strokes to action triggers
			type = OptionType.ACTION_TRIGGER;
			if (defaultValue is KeyStroke keyStroke) {
				defaultValue = new ActionTrigger(keyStroke);
			}
		}

		return new ToolOption(optionName, type, null, null, defaultValue, false, null);
	}

	/* @Override */
	protected bool notifyOptionChanged(string optionName, object oldValue, object newValue) {
		NotifyListenersRunnable runnable =
			new NotifyListenersRunnable(optionName, oldValue, newValue);
		Swing.runNow(runnable);

		OptionsVetoException veto = runnable.getVetoException();
		if (veto != null) {
			throw veto;
		}

		return true;
	}

	/* @Override */
	public void dispose() {
		base.dispose();
		listeners.clear();
	}

	private class NotifyListenersRunnable : Runnable {
		private string optionName;
		private object oldValue;
		private object newValue;
		private OptionsVetoException veto;

		NotifyListenersRunnable(string optionName, object oldValue, object newValue) {
			this.optionName = optionName;
			this.oldValue = oldValue;
			this.newValue = newValue;
		}

		/* @Override */
		public void run() {
			List<OptionsChangeListener> notifiedListeners = new();
			try {
				foreach (OptionsChangeListener listener in listeners) {
					listener.optionsChanged(this, optionName, oldValue, newValue);
					notifiedListeners.add(listener);
				}
			}
			catch (OptionsVetoException e) {
				veto = e;
				foreach (OptionsChangeListener notifiedListener in notifiedListeners) {
					notifiedListener.optionsChanged(this, optionName, newValue,
						oldValue);
				}
			}
		}

		OptionsVetoException getVetoException() {
			return veto;
		}

	}

}
